export function getPreRenderedDiagram(code: string, isDark: boolean): string | null {
  const normalized = code.trim();
  if (normalized.includes("flowchart TB") && normalized.includes("Ingestion and Edge Layer")) {
    return isDark ? PRE_RENDERED_DIAGRAMS["payroll-flowchart-tb"].dark : PRE_RENDERED_DIAGRAMS["payroll-flowchart-tb"].light;
  }
  if (normalized.includes("flowchart LR") && normalized.includes("Immutable Inputs")) {
    return isDark ? PRE_RENDERED_DIAGRAMS["payroll-flowchart-lr"].dark : PRE_RENDERED_DIAGRAMS["payroll-flowchart-lr"].light;
  }
  if (normalized.includes("sequenceDiagram") && normalized.includes("RBAC Permission Resolver")) {
    return isDark ? PRE_RENDERED_DIAGRAMS["payroll-sequence"].dark : PRE_RENDERED_DIAGRAMS["payroll-sequence"].light;
  }
  return null;
}
